package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.MagicLinkExpiryMinutesVO;

class MagicLinkExpiryMinutesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of magic link expiry minutes of tenant config")
  void test_magic_link_expiry_minutes_value_holder_assign_plain_value() {
    Object holder = new Object();
    MagicLinkExpiryMinutesValueHolder<Object> value =
        new MagicLinkExpiryMinutesValueHolder<>(holder);
    Assertions.assertSame(holder, value.magicLinkExpiryMinutes(1),
        "Setters must return the holder");
    Assertions.assertTrue(value.getMagicLinkExpiryMinutesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getMagicLinkExpiryMinutes().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of magic link expiry minutes of tenant config")
  void test_magic_link_expiry_minutes_value_holder_assign_value_object() {
    Object holder = new Object();
    MagicLinkExpiryMinutesValueHolder<Object> value =
        new MagicLinkExpiryMinutesValueHolder<>(holder);
    MagicLinkExpiryMinutesVO vo = MagicLinkExpiryMinutesVO.from(1);
    Assertions.assertFalse(value.getMagicLinkExpiryMinutesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.magicLinkExpiryMinutes(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getMagicLinkExpiryMinutesValue().orElseThrow());
    Assertions.assertSame(holder, value.magicLinkExpiryMinutes(Optional.empty()));
    Assertions.assertFalse(value.getMagicLinkExpiryMinutesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.magicLinkExpiryMinutes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMagicLinkExpiryMinutesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of magic link expiry minutes of tenant config against the original")
  void test_magic_link_expiry_minutes_value_holder_read() {
    Object holder = new Object();
    MagicLinkExpiryMinutesValueHolder<Object> value =
        new MagicLinkExpiryMinutesValueHolder<>(holder);
    MagicLinkExpiryMinutesVO vo = MagicLinkExpiryMinutesVO.from(1);
    MagicLinkExpiryMinutesVO other = MagicLinkExpiryMinutesVO.from(1);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getMagicLinkExpiryMinutesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMagicLinkExpiryMinutes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readMagicLinkExpiryMinutes(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.magicLinkExpiryMinutes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMagicLinkExpiryMinutes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMagicLinkExpiryMinutes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of magic link expiry minutes of tenant config")
  void test_magic_link_expiry_minutes_value_holder_unset() {
    Object holder = new Object();
    MagicLinkExpiryMinutesValueHolder<Object> value =
        new MagicLinkExpiryMinutesValueHolder<>(holder);
    MagicLinkExpiryMinutesVO vo = MagicLinkExpiryMinutesVO.from(1);
    value.magicLinkExpiryMinutes(vo);
    Assertions.assertSame(holder,
        value.unsetMagicLinkExpiryMinutesIfMatches("magicLinkExpiryMinutes_other"));
    Assertions.assertTrue(value.getMagicLinkExpiryMinutesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetMagicLinkExpiryMinutesIfMatches("magicLinkExpiryMinutes"));
    Assertions.assertFalse(value.getMagicLinkExpiryMinutesValue().isPresent(),
        "The field name must clear the value");
    value.magicLinkExpiryMinutes(vo);
    Assertions.assertSame(holder, value.unsetMagicLinkExpiryMinutes());
    Assertions.assertFalse(value.getMagicLinkExpiryMinutesValue().isPresent(),
        "Unset must clear the value");
  }
}
